import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Этика культивации и границы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/19-修炼伦理与边界.md","filePath":"ru/19-修炼伦理与边界.md","lastUpdated":null}'),e={name:"ru/19-修炼伦理与边界.md"};function o(d,t,n,h,s,u){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="этика-культивации-и-границы" tabindex="-1">Этика культивации и границы <a class="header-anchor" href="#этика-культивации-и-границы" aria-label="Permalink to &quot;Этика культивации и границы&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>19</td></tr><tr><td>Модуль</td><td>Космические законы и системы культивации</td></tr><tr><td>Ключевые слова</td><td>Этика культивации, Границы, Табу, Моральная граница, Этическая проверка</td></tr></tbody></table><h2 id="i-определение-и-статус-этики-культивации" tabindex="-1">I. Определение и статус этики культивации <a class="header-anchor" href="#i-определение-и-статус-этики-культивации" aria-label="Permalink to &quot;I. Определение и статус этики культивации&quot;">​</a></h2><p>Этика культивации — совокупность моральных и правовых норм Симбиотической Цивилизации Якоря, регулирующих поведение практиков, очерчивающих границы культивации и поддерживающих порядок культивации. В эпоху хищничества культивация считалась «привилегией сильных», и практики ради силы шли на всё: пожирали чужой Исток, порабощали чужие души, грабили чужие ресурсы, проводили бесчеловечные эксперименты. Такая культура «сила превыше всего, этика ничто» — глубочайшая духовная основа хищнической системы.</p><p>После установления Симбиотической Цивилизации Якоря строительство этики культивации стало одной из центральнейших задач духовной цивилизации. Ключевой тезис этики: «Получение и использование силы должны быть ограничены этикой». Цивилизация считает: культивация — не чисто личное дело, а общественное, касающееся других, цивилизации и всего космоса. Практики, стремясь к росту силы, обязаны уважать права других, поддерживать порядок цивилизации, беречь экологию космоса. Этика культивации — не оковы, а стража: она обеспечивает путь «симбиотической эволюции», не давая скатиться в пропасть «хищнического уничтожения».</p><p>Этика культивации занимает высокое место в правовой системе цивилизации. Симбиотическая Конституция закрепляет базовые принципы этики; при Суде Якорей действует специальный «Этический трибунал»; аттестация уровней всех продвинутых практиков проходит этическую проверку. Этика культивации — не факультативное «мягкое» правило, а обязательная «жёсткая» норма.</p><h2 id="ii-базовые-принципы-этики-культивации" tabindex="-1">II. Базовые принципы этики культивации <a class="header-anchor" href="#ii-базовые-принципы-этики-культивации" aria-label="Permalink to &quot;II. Базовые принципы этики культивации&quot;">​</a></h2><h3 id="_2-1-принцип-достоинства-жизни" tabindex="-1">2.1 Принцип достоинства жизни <a class="header-anchor" href="#_2-1-принцип-достоинства-жизни" aria-label="Permalink to &quot;2.1 Принцип достоинства жизни&quot;">​</a></h3><p>Каждая жизнь обладает неприкосновенным достоинством и ценностью; культивация не может идти ценой ущерба достоинству жизни. Конкретно:</p><ul><li>Запрет использовать другие жизни как «материал» или «инструмент» культивации</li><li>Запрет бесчеловечных экспериментов (вивисекция, пытки душ и т.п.)</li><li>Запрет порабощения и контроля свободной воли других жизней</li><li>Уважение права каждой жизни выбирать свой путь эволюции; запрет принуждать других культивировать по-своему</li></ul><h3 id="_2-2-принцип-анти-хищничества" tabindex="-1">2.2 Принцип анти-хищничества <a class="header-anchor" href="#_2-2-принцип-анти-хищничества" aria-label="Permalink to &quot;2.2 Принцип анти-хищничества&quot;">​</a></h3><p>Культивация должна опираться на симбиотическую циркуляцию, а не на грабёж других. Конкретно:</p><ul><li>Запрет пожирать и грабить Исток, энергию, удачу других жизней</li><li>Запрет ускорять свою культивацию или повышать уровень за счёт вреда другим</li><li>Запрет монополизировать ресурсы ради неправомерной выгоды</li><li>Запрет оправдывать хищничество «законом джунглей»</li></ul><h3 id="_2-3-принцип-информированного-согласия" tabindex="-1">2.3 Принцип информированного согласия <a class="header-anchor" href="#_2-3-принцип-информированного-согласия" aria-label="Permalink to &quot;2.3 Принцип информированного согласия&quot;">​</a></h3><p>Культивационные действия, затрагивающие других (наставничество, парная практика, обмен энергией, эксперименты и т.д.), допустимы только при полной информированности и добровольном согласии стороны. Конкретно:</p><ul><li>Полное разъяснение содержания, рисков и выгод действия</li><li>Обеспечение полной способности самостоятельного суждения, без принуждения и подкупа</li><li>Право стороны выйти в любой момент; запрет принуждения к продолжению</li><li>Для несовершеннолетних и недееспособных согласие дают опекуны на основе профессиональной оценки</li></ul><h3 id="_2-4-принцип-минимального-вреда" tabindex="-1">2.4 Принцип минимального вреда <a class="header-anchor" href="#_2-4-принцип-минимального-вреда" aria-label="Permalink to &quot;2.4 Принцип минимального вреда&quot;">​</a></h3><p>Культивация должна по возможности избегать вреда другим и среде. При неизбежности влияния выбирается наименее вредный способ и возмещается причинённый ущерб. Конкретно:</p><ul><li>Эксперименты — преимущественно в Изолированном Пространстве, чтобы не распространять риски</li><li>Боевая культивация — на специальных площадках, избегая ущерба общественной среде</li><li>Энергетические загрязнения, повреждения пространства вовремя очищаются и восстанавливаются</li><li>Запрет высокорисковых действий в густонаселённых зонах</li></ul><h3 id="_2-5-принцип-честности" tabindex="-1">2.5 Принцип честности <a class="header-anchor" href="#_2-5-принцип-честности" aria-label="Permalink to &quot;2.5 Принцип честности&quot;">​</a></h3><p>Практики честны в вопросах культивации, без обмана. Конкретно:</p><ul><li>Запрет подделки уровней, величин вклада, результатов экзаменов</li><li>Запрет фальсификаций и плагиата в опыте и исследованиях</li><li>Запрет ложных сведений в заявках на ресурсы и проекты</li><li>Запрет выманивать ресурсы или доверие ложными обещаниями</li></ul><h3 id="_2-6-принцип-ответственности" tabindex="-1">2.6 Принцип ответственности <a class="header-anchor" href="#_2-6-принцип-ответственности" aria-label="Permalink to &quot;2.6 Принцип ответственности&quot;">​</a></h3><p>Больше сила — больше ответственность. Продвинутые практики несут общественные обязанности, соразмерные силе. Конкретно:</p><ul><li>Достигшие определённого уровня обязаны наставлять младших</li><li>Продвинутые обязаны участвовать в обслуживании якорей, охране цивилизации</li><li>Практик отвечает за последствия собственной культивации, без уклонения</li><li>При кризисе цивилизации продвинутые обязаны выступить вперёд</li></ul><h2 id="iii-абсолютные-табу-культивации" tabindex="-1">III. Абсолютные табу культивации <a class="header-anchor" href="#iii-абсолютные-табу-культивации" aria-label="Permalink to &quot;III. Абсолютные табу культивации&quot;">​</a></h2><p>Следующие действия — «абсолютные табу»: ни один практик не вправе касаться их ни при каких обстоятельствах; нарушители подвергаются строжайшим санкциям:</p><table tabindex="0"><thead><tr><th>Тип табу</th><th>Конкретное действие</th><th>Санкции</th></tr></thead><tbody><tr><td>Хищничество Истока</td><td>Пожирание, грабёж Истока или жизненного ядра других</td><td>Лишение культивации, пожизненное заключение, при отягчающих — уничтожение Истока</td></tr><tr><td>Порабощение душ</td><td>Превращение жизней в инструменты контролем душ, духовным рабством</td><td>Лишение культивации, принудительная этическая перековка, пожизненное лишение права культивации</td></tr><tr><td>Геноцид рас</td><td>Систематическое истребление расы ради культивации</td><td>Высший суд Суда Якорей, высшая мера</td></tr><tr><td>Уничтожение планов</td><td>Уничтожение целого плана ради ресурсов или силы</td><td>Высшая мера и полная ответственность за восстановление плана</td></tr><tr><td>Бесчеловечные эксперименты</td><td>Бесчеловечные опыты над разумными существами</td><td>Лишение культивации, пожизненное заключение, уничтожение всех результатов</td></tr><tr><td>Преступление времени</td><td>Крупные искажения истории или убийства возвратом времени</td><td>Высшая мера, пожизненное лишение временных способностей</td></tr><tr><td>Загрязнение законов</td><td>Умышленное загрязнение изначальных законов, необратимый ущерб космосу</td><td>Высшая мера и очищение законов высшим органом цивилизации</td></tr></tbody></table><p>Установление табу выражает твёрдую позицию цивилизации по границе этики. В табу нет «серой зоны» и «смягчающих обстоятельств»: любое касание — строжайшие санкции.</p><h2 id="iv-серые-зоны-этики-культивации-и-принципы-их-решения" tabindex="-1">IV. Серые зоны этики культивации и принципы их решения <a class="header-anchor" href="#iv-серые-зоны-этики-культивации-и-принципы-их-решения" aria-label="Permalink to &quot;IV. Серые зоны этики культивации и принципы их решения&quot;">​</a></h2><p>Кроме явных запретов существуют «серые зоны» — сами по себе не абсолютное добро или зло; их этическая природа зависит от ситуации, мотива, способа и последствий. Для серых зон цивилизация применяет принципы:</p><h3 id="_4-1-частые-серые-зоны" tabindex="-1">4.1 Частые серые зоны <a class="header-anchor" href="#_4-1-частые-серые-зоны" aria-label="Permalink to &quot;4.1 Частые серые зоны&quot;">​</a></h3><ul><li><strong>Вред в боевой культивации</strong>: партнёры могут ранить друг друга; этичность зависит от информированного согласия и разумности вреда</li><li><strong>Конкуренция за ресурсы</strong>: этичность зависит от честности способа и соблюдения антимонопольных правил</li><li><strong>Асимметрия власти «наставник-ученик»</strong>: естественный дисбаланс; злоупотребление властью оценивается конкретно</li><li><strong>Принятие риска</strong>: высокорисковые методы; добровольность требует оценки информированности о риске и наличия альтернатив</li><li><strong>Межрасовая кооперация</strong>: культурные различия и дисбаланс власти требуют конкретной оценки</li></ul><h3 id="_4-2-принципы-решения" tabindex="-1">4.2 Принципы решения <a class="header-anchor" href="#_4-2-принципы-решения" aria-label="Permalink to &quot;4.2 Принципы решения&quot;">​</a></h3><p>Для этических вопросов серых зон — способ «анализ конкретной ситуации + оценка этического комитета + руководство прецедентами»:</p><ol><li><strong>Анализ ситуации</strong>: без «одного на всех» — комплексное суждение по ситуации, мотиву, способу, последствиям</li><li><strong>Оценка комитета</strong>: сложные вопросы передаются «Этическому комитету» при Суде Якорей для профессиональной оценки</li><li><strong>Прецеденты</strong>: результаты формируют прецеденты для последующих аналогичных дел</li><li><strong>Образование прежде</strong>: для нарушений в серых зонах приоритетны обучение и исправление, а не прямое наказание</li><li><strong>Динамическая корректировка</strong>: критерии серых зон могут пересматриваться с развитием цивилизации и углублением понимания</li></ol><h2 id="v-образование-и-интериоризация-этики-культивации" tabindex="-1">V. Образование и интериоризация этики культивации <a class="header-anchor" href="#v-образование-и-интериоризация-этики-культивации" aria-label="Permalink to &quot;V. Образование и интериоризация этики культивации&quot;">​</a></h2><p>Поддержание этики невозможно только санкциями и надзором — требуется внутреннее признание и интериоризация. Цивилизация создала системную систему этического образования:</p><h3 id="_5-1-базовое-образование" tabindex="-1">5.1 Базовое образование <a class="header-anchor" href="#_5-1-базовое-образование" aria-label="Permalink to &quot;5.1 Базовое образование&quot;">​</a></h3><ul><li>Этика — обязательный курс для всех практиков с уровня Ощущения Истока</li><li>Содержание: принципы, списки табу, разбор случаев, моделирование ситуаций</li><li>Методы: занятия, дискуссии, ролевые игры, личный пример наставников</li></ul><h3 id="_5-2-продвинутое-образование" tabindex="-1">5.2 Продвинутое образование <a class="header-anchor" href="#_5-2-продвинутое-образование" aria-label="Permalink to &quot;5.2 Продвинутое образование&quot;">​</a></h3><ul><li>С ростом уровня растут глубина и широта этического образования</li><li>Продвинутые изучают сложные вопросы (этика между планами, этика времени, этика творения миров)</li><li>Практики выше Дао Истока сдают «продвинутый этический экзамен» для дальнейшего роста</li></ul><h3 id="_5-3-практика-и-интериоризация" tabindex="-1">5.3 Практика и интериоризация <a class="header-anchor" href="#_5-3-практика-и-интериоризация" aria-label="Permalink to &quot;5.3 Практика и интериоризация&quot;">​</a></h3><ul><li>Поощрение практики этики в повседневной культивации, превращение требований в привычку</li><li>Система избрания «этических образцов» для поощрения выдающихся</li><li>Наставники обязаны передавать этический дух наряду с техникой — «и Дао, и искусство»</li></ul><h2 id="vi-надзор-и-исполнение-этики-культивации" tabindex="-1">VI. Надзор и исполнение этики культивации <a class="header-anchor" href="#vi-надзор-и-исполнение-этики-культивации" aria-label="Permalink to &quot;VI. Надзор и исполнение этики культивации&quot;">​</a></h2><h3 id="_6-1-механизмы-надзора" tabindex="-1">6.1 Механизмы надзора <a class="header-anchor" href="#_6-1-механизмы-надзора" aria-label="Permalink to &quot;6.1 Механизмы надзора&quot;">​</a></h3><ul><li><strong>Мониторинг сети якорей</strong>: непрерывное наблюдение за практиками, сигналы о подозрениях</li><li><strong>Система доносов</strong>: любое существо может сообщить в Этический трибунал; доносители защищены</li><li><strong>Периодическая этическая проверка</strong>: практики уровня Закона Истока и выше ежегодно проходят проверку, результаты в личном деле</li><li><strong>Надзор организаций</strong>: внутренний надзор сообществ и организаций за этикой членов</li></ul><h3 id="_6-2-механизмы-исполнения" tabindex="-1">6.2 Механизмы исполнения <a class="header-anchor" href="#_6-2-механизмы-исполнения" aria-label="Permalink to &quot;6.2 Механизмы исполнения&quot;">​</a></h3><ul><li><strong>Этический трибунал</strong>: специальный орган при Суде Якорей для дел об этике</li><li><strong>Градация санкций</strong>: от предупреждения, штрафа, списания вклада, ограничения прав до лишения культивации, пожизненного заключения и высшей меры</li><li><strong>Этическая перековка</strong>: для раскаявшихся — перековка наряду с санкциями, частичное восстановление прав</li><li><strong>Судимость</strong>: записи о нарушениях остаются в деле навсегда, влияя на аттестацию, распределение ресурсов, должности</li></ul><h2 id="vii-динамическое-расширение-границ-культивации" tabindex="-1">VII. Динамическое расширение границ культивации <a class="header-anchor" href="#vii-динамическое-расширение-границ-культивации" aria-label="Permalink to &quot;VII. Динамическое расширение границ культивации&quot;">​</a></h2><p>Этика и границы — не догмы, а живые нормы, динамически меняющиеся с развитием цивилизации, технологий и понимания. Механизм динамического расширения:</p><ol><li><strong>Этическая оценка новых технологий</strong>: каждую новую технику или применение закона сначала оценивают этически; после одобрения — внедрение</li><li><strong>Этическое обсуждение новых сценариев</strong>: при новых этапах (эпоха межпланов, межзвёздная эпоха) — специальные обсуждения и нормы для новых сценариев</li><li><strong>Периодическая редакция норм</strong>: конкретные нормы пересматриваются каждые пятьдесят лет с широким сбором мнений всех существ</li><li><strong>Накопление прецедентов</strong>: решения Этического трибунала обогащают и уточняют содержание этики</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Этика культивации и границы — духовный стержень Симбиотической Цивилизации Якоря. Она отвечает на фундаментальный вопрос: «Каким человеком должен стать практик?» Ответ цивилизации: практик должен быть человеком с силой, а тем более с моралью; человеком, в ком личная эволюция и симбиоз Десяти Тысяч Рас едины; человеком, который стремится к силе, но никогда ею не порабощён. Этика культивации — не оковы силы, а её возвышение: она обеспечивает, чтобы сила всегда служила достоинству жизни и прогрессу цивилизации, а не становилась орудием уничтожения и грабежа. В космосе, где сила способна двигать горы и моря, творить и губить миры, этика культивации — последний и важнейший рубеж защиты границы цивилизации.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Центральные тезисы анти-хищничества)</li><li>17-位面至高强者标准 (Стандарты верховных экспертов планов)</li><li>48-司法体系与裁决机制 (Судебная система и механизм решений)</li></ul>',56)])])}const _=a(e,[["render",o]]);export{b as __pageData,_ as default};
